const register=async()=>{const payload=commandPayload();const names=payload.map(x=>x.name);if(new Set(names).size!==names.length)throw new Error('Duplicate Discord command name detected: '+names.join(', '));console.log('Registering RustPulse Pop commands: '+names.join(', '));const guildRoute=process.env.GUILD_ID?.trim()?Routes.applicationGuildCommands(process.env.CLIENT_ID.trim(),process.env.GUILD_ID.trim()):null;try{const route=guildRoute||Routes.applicationCommands(process.env.CLIENT_ID.trim());await rest.put(route,{body:payload});console.log((guildRoute?'Guild':'Global')+' command registration succeeded: '+payload.length+' commands.');}catch(error){if(error?.code===50001&&guildRoute){console.error('Guild command registration denied; retrying global registration. Check CLIENT_ID, GUILD_ID, and bot installation.');await rest.put(Routes.applicationCommands(process.env.CLIENT_ID.trim()),{body:payload});console.log('Global fallback registration succeeded: '+payload.length+' commands.');}else{console.error('Discord command registration failed:',error?.status,error?.code,error?.message);throw error;}}};
