function normalize(raw){const rows=Array.isArray(raw.players)?raw.players.map((p,i)=>typeof p==='string'?{name:p}:({name:p.name||p.username||'Unnamed survivor',platform:p.platform||p.device||'Platform unavailable',playing:p.playing||p.activity||'RustPulse'})):[];const n=raw.currentPlayers??raw.playersOnline??raw.online??raw.population??(Array.isArray(raw.players)?raw.players.length:null);return {serverName:raw.serverName||raw.name||process.env.RUST_SERVER_NAME||'RustPulse Server',current:Number.isFinite(Number(n))?Number(n):null,max:raw.maxPlayers??raw.capacity??null,rows};}
function parseEndpoint(p){const raw=(p.ip||p.host||'').trim();const m=raw.match(/^([^:]+)(?::(\\d+))?$/);if(!m)throw Error('Server host/IP must look like 203.0.113.10:28016');const host=p.host?.trim()||m[1];const port=Number(m[2]||p.rconPort||28016);if(!p.rconPassword)throw Error('RCON password is not configured');return {host,port};}
function parsePlayers(message){let text=typeof message==='string'?message:JSON.stringify(message);let parsed;try{parsed=JSON.parse(text);}catch{}const list=Array.isArray(parsed)?parsed:(parsed?.players||parsed?.Players||parsed?.data?.players);if(Array.isArray(list))return list.map((p,i)=>typeof p==='string'?{name:p,platform:'Console'}:{name:p.displayName||p.username||p.name||'Unnamed survivor',platform:p.platform||p.device||'Console',playing:p.playing||'RustPulse'});return text.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean).filter(x=>!/^players?\\s*$/i.test(x)).map((x,i)=>({name:x.replace(/^[-*]\\s*/, '').slice(0,80),platform:'Console',playing:'RustPulse'}));}
function rconRequest(profile,command='global.playerlist'){const {host,port}=parseEndpoint(profile);const scheme=String(process.env.RCON_TLS||'').toLowerCase()==='true'?'wss':'ws';const url=scheme+'://'+host+':'+port+'/'+encodeURIComponent(profile.rconPassword);return new Promise((resolve,reject)=>{const ws=new WebSocket(url);let done=false;const finish=(fn,v)=>{if(done)return;done=true;clearTimeout(timer);try{ws.close()}catch{};fn(v);};const timer=setTimeout(()=>finish(reject,Error('RCON timed out after 10 seconds')),10000);ws.on('open',()=>ws.send(JSON.stringify({Identifier:1,Message:command,Name:'WebRcon',Type:'Generic'})));ws.on('message',raw=>{try{const packet=JSON.parse(raw.toString());if(packet.Identifier===1||packet.Message!==undefined)finish(resolve,packet.Message??packet);}catch{finish(reject,Error('RCON returned invalid JSON'));}});ws.on('error',err=>finish(reject,Error('RCON connection failed: '+err.message)));ws.on('close',()=>{if(!done)finish(reject,Error('RCON closed before replying'));});});}
function parseJsonOrText(message){if(typeof message!=='string')return message;try{return JSON.parse(message);}catch{return {text:message};}}
async function fetchRconSnapshot(guildId){const p=serverProfiles.get(guildId);if(!p)throw Error('Run /pop setup and configure the Rust server first');if(!p.rconPassword)throw Error('RCON password is missing. Open /pop setup and click Add RCON password.');const optional=async(command)=>{try{return {ok:true,data:await rconRequest(p,command)};}catch(error){return {ok:false,error:error.message};}};const [infoResult,playersResult,statusResult,usersResult]=await Promise.all([optional('server.info'),optional('playerlist'),optional('status'),optional('users')]);if(!playersResult.ok)throw Error('playerlist failed: '+playersResult.error);const info=parseJsonOrText(infoResult.ok?infoResult.data:{});const players=parseJsonOrText(playersResult.data);const rows=parsePlayers(players?.players??players?.Players??players?.data?.players??playersResult.data);const current=Number(info?.players??info?.currentPlayers??info?.online??info?.playerCount??rows.length);const d={serverName:p.name,current:Number.isFinite(current)?current:rows.length,max:info?.maxPlayers??info?.maxplayers??info?.capacity??null,rows,info,status:statusResult.ok?statusResult.data:null,users:usersResult.ok?usersResult.data:null,queue:info?.queue??info?.joining??null,map:info?.map??info?.level??null,checks:{serverInfo:infoResult.ok,playerlist:playersResult.ok,status:statusResult.ok,users:usersResult.ok}};const sample={at:Date.now(),current:d.current,max:d.max,map:d.map,queue:d.queue};const history=populationHistory.get(guildId)||[];history.push(sample);while(history.length>historyLimit)history.shift();populationHistory.set(guildId,history);rconCache.set(guildId,{data:d,at:sample.at,error:null});return d;}
async function fetchRcon(guildId){return (await fetchRconSnapshot(guildId));}
async function getPop(guildId){const hit=rconCache.get(guildId);if(hit&&Date.now()-hit.at<refreshMs)return hit.data;try{return await fetchRcon(guildId)}catch(e){if(hit){hit.error=e.message;return hit.data}throw e;}}
