function rulesHub(){return brand('OFFICIAL RULES & GUIDELINES').setDescription('**Welcome to the RustPulse Pop guide.**\n\nEverything you need is behind the buttons below: how to behave, how to connect a server, what each command does, and what information must stay private.\n\n**🟠 General information**\nThis bot is free and read-only. It shows live fields returned by an authorised RCON connection; it does not invent missing data.\n\n**📚 Use the guide**\nChoose a section from the menu, or use the buttons to switch between the full terms, rules, and privacy pages.').addFields({name:'Quick start',value:'1. The server owner runs /pop setup.\n2. Choose Setup server and enter the server details.\n3. Add the RCON password through the private modal.\n4. Run /pop test.\n5. Use /pop view to open the live dashboard.'},{name:'Important',value:'Never post passwords, tokens, webhook URLs, IP addresses, or private screenshots. If one is exposed, rotate it immediately.'}).setFooter({text:infoFooter});}
function sectionEmbed(value){const sections={start:['🧭 START HERE','RustPulse Pop is a free, read-only Discord tool. The server owner controls setup. Start with /pop setup, finish the private RCON prompt, run /pop test, then use /pop view.'],discord:['💬 DISCORD CONDUCT','Be respectful. No harassment, threats, hate speech, targeted humiliation, spam, or attempts to expose private information. Follow Discord Terms and local staff instructions.'],game:['🎮 IN-GAME CONDUCT','Play fairly and follow the Rust server rules. Do not use player tracking to target, intimidate, stalk, or publish information about another player.'],setup:['🛠️ SETUP GUIDE','Only the Discord server owner can configure the bot. Run /pop setup, choose Setup server, enter the server name, IPv4 address, RCON port, region, and optional description, then submit. Click Add RCON password and enter it in the private modal. Run /pop test; a successful test confirms the bot can read the player list. Choose automatic updates last.'],commands:['⚡ COMMAND GUIDE','/pop view opens the live population and roster.\n/pop status shows connection health and the last successful check.\n/pop test checks RCON and the player list; it is owner-only.\n/pop setup opens the owner control panel.\n/searchplayer username privately looks up a connected player for an authorised manager or owner.\n/terms and /rules open this guide; the owner can add target_channel to post a panel publicly.'],rcon:['🔐 RCON, DATA & PRIVACY','Use only a server you are authorised to monitor. Keep the RCON password, Discord token, webhook URL, IP address, and private screenshots out of chat and GitHub. Public population panels hide connection details. Player fields are limited to what RCON returns. Do not scrape, resell, redistribute, stalk, or profile players.']};const [title,text]=sections[value]||sections.start;return brand(title).setDescription(text+'\n\nUse the buttons above to switch pages or open another guide section.').setFooter({text:infoFooter});}
