function dashboard(d, meta = {}) {
  const updated = meta.at || Date.now();
  const stale = Boolean(meta.error);
  const count = Number.isFinite(Number(d.current)) ? Number(d.current) : d.rows.length;
  const capacity = d.max !== null && d.max !== undefined ? String(d.max) : '—';
  const occupancy = d.max ? Math.min(100, Math.round((count / Number(d.max)) * 100)) : null;
  const bar = occupancy === null ? '░░░░░░░░░░' : '█'.repeat(Math.round(occupancy / 10)) + '░'.repeat(10 - Math.round(occupancy / 10));
  const state = stale ? '🟠 DELAYED' : '🟢 LIVE';
  const headline = count === 0 ? 'The coast is quiet.' : count === 1 ? 'One survivor is online.' : count + ' survivors are online.';
  const e = brand('LIVE SERVER PULSE').setDescription('**' + String(d.serverName || 'Rust server').slice(0, 100) + '**\n' + headline + '\n\n' + bar + (occupancy === null ? '' : '  **' + occupancy + '%** capacity') + (stale ? '\n\n⚠️ This is the last successful snapshot.' : '')).addFields({name:'SIGNAL',value:state,inline:true},{name:'ONLINE',value:'**' + count + '** / ' + capacity,inline:true},{name:'FRESHNESS',value:'<t:' + Math.floor(updated / 1000) + ':R>',inline:true});
  const pulse=[]; if(d.map) pulse.push('🗺️ **Map**\n' + String(d.map).slice(0, 80)); if(d.queue !== null && d.queue !== undefined) pulse.push('⏳ **Queue**\n' + String(d.queue)); if(d.region) pulse.push('📍 **Region**\n' + String(d.region).slice(0, 60)); if(pulse.length) e.addFields({name:'SERVER TELEMETRY',value:pulse.join('     ')});
  if(d.rows.length) e.addFields({name:'‍ ACTIVE ROSTER •' + d.rows.length + ' listed',value:d.rows.slice(0, 20).map((p,i)=>'**' + String(i+1).padStart(2,'0') + '  ' + val(p.name,'Unknown survivor') + '**  ·  ' + val(p.platform,'Console') + (p.ping ? '  ·  ' + p.ping + 'ms' : '')).join('\n').slice(0, 3900)});
  else e.addFields({name:'‍ ACTIVE ROSTER',value:count === 0 ? 'No connected players were returned.' : 'The server returned population but no individual roster.'});
  e.addFields({name:'PRIVACY BY DESIGN',value:'Public view hides IP, RCON port, region, credentials, and private configuration. Missing fields remain unavailable.'});
  return e;
}

